function resetLayoutWork(){pdfAbort?.abort();pdfAbort=null;layoutTarget=null;draftSubmission=null;}
function assertLayoutTarget(target){if(!target||target.generation!==generation||target.courseId!==course?.id||target.version!==snapshot?.version||tab!=='layout'||!admin())throw Error('학급·권한 또는 기준 버전이 바뀌었습니다. 현재 학급을 새로고침한 뒤 다시 검토하세요.');}
