function representativesView(){const root=q('#content'),id=course.id,g=generation;if(!admin())return;const ui=mountStudentRepresentatives(root,{isCurrent:()=>g===generation&&course?.id===id&&tab==='representatives'&&root.isConnected,list:()=>api.rpc('hafs_student_representatives',{p_course:id}),assign:values=>api.edge('student-representatives',{courseId:id,...values}),remove:(slot,expected)=>api.rpc('hafs_remove_student_representative',{p_course:id,p_slot:slot,p_expected:expected}),resetPassword:(studentNumber,schoolYear)=>openCredentialDialog({dialog,action:'reset-password',target:{kind:'student',courseId:id,schoolYear,studentNumber},isCurrent:()=>g===generation&&course?.id===id&&tab==='representatives',request:args=>api.edge('account-credentials',args),onDone:()=>ui.refresh()})});ui.refresh().catch(fail);}

