async function refreshCourseList(){const g=generation,id=course?.id;const next=await api.rpc('hafs_my_courses');if(g!==generation||course?.id!==id)return;const selected=next.find(c=>c.id===id);if(!selected){await signout('학급 접근 권한을 확인할 수 없어 로그아웃했습니다.');return;}courses=next;course=selected;updateCoursePickers();}

