window.addEventListener('beforeunload',e=>{if(schoolImportUI?.hasDraft()){e.preventDefault();e.returnValue='';}});

async function syncSchoolImportViews(){
 if(!api.access||!course)return;
 const g=generation,id=course.id;
 // Invalidate stale data before reads so an unsuccessful refresh cannot expose old counts.
 snapshot=null;roster=[];photos=[];queue=[];audit=[];historyData=null;
 try{
  await refreshCourseList();
  if(g!==generation||course?.id!==id||!api.access)return;
  await refresh(true);
  if(g===generation&&course?.id===id&&!snapshot)throw Error('현재 학급 자료를 아직 불러오지 못했습니다.');
 }catch(error){
  if(g!==generation||course?.id!==id)return;
  render();
  if(tab==='school'&&schoolImportUI){const progress=document.createElement('section');app.querySelector('main')?.append(progress);schoolImportUI.attach(progress);}
  throw Error('등록 진행 결과는 유지됩니다. 현재 학급 화면 갱신에 실패했으니 다시 불러오기를 눌러 주세요. '+friendly(error));
 }
}

function coursePickerFields(){
 const key=periodKey(course),visible=coursesForPeriod(courses,key);
 if(!admin()&&snapshot)return `<label class="teacher-course">학급<select id="course" class="course-picker" aria-label="학급">${visible.map(c=>`<option value="${h(c.id)}" ${c.id===course?.id?'selected':''}>${h(courseLabel(c))}</option>`).join('')}</select></label><span class="teacher-period">${h(periodOptions(courses).find(p=>p.key===key)?.label??'학기')}</span><details id="term-menu"><summary aria-label="학년도·학기 변경" title="학년도·학기 변경">✎</summary><div class="teacher-popover"><label>학년도·학기<select id="period" aria-label="학년도·학기">${periodOptions(courses).map(p=>`<option value="${h(p.key)}" ${p.key===key?'selected':''}>${h(p.label)}</option>`).join('')}</select></label></div></details>`;
 return `<label>학년도·학기<select id="period" aria-label="학년도·학기">${periodOptions(courses).map(p=>`<option value="${h(p.key)}" ${p.key===key?'selected':''}>${h(p.label)}</option>`).join('')}</select></label><label>학급<select id="course" class="course-picker" aria-label="학급">${visible.map(c=>`<option value="${h(c.id)}" ${c.id===course?.id?'selected':''}>${h(courseLabel(c))} · ${c.role==='admin'?'관리자':'교사'}</option>`).join('')}</select></label>`;
}
function coursePickers(){return `<div id="course-selectors" class="flex-form">${coursePickerFields()}</div>`;}
function bindCoursePickers(){
 const reset=()=>{if(q('#period'))q('#period').value=periodKey(course);if(q('#course'))q('#course').value=course?.id??'';};
 q('#course').onchange=()=>{if(busy){reset();return;}return act(async()=>{try{await selectCourse(q('#course').value);}finally{reset();}});};
 q('#period').onchange=()=>{if(busy){reset();return;}const key=q('#period').value;return act(async()=>{try{const next=coursesForPeriod(courses,key)[0];if(!next)throw Error('이 학기에 접근 가능한 학급이 없습니다.');if(next.id!==course?.id)await selectCourse(next.id);}finally{reset();}});};
}
function updateCoursePickers(){const picker=q('#course-selectors');if(picker){picker.innerHTML=coursePickerFields();bindCoursePickers();}}

function teacherChrome(total){return `<header class="teacher-tools"><div class="teacher-top">${coursePickers()}<button id="refresh">새로고침</button><button id="class-mode" aria-pressed="${classMode}">${classMode?'수업 모드 종료':'수업 모드'}</button><button data-tab="history" class="mode-history">기록·취소</button><details id="teacher-more"><summary>더보기</summary><div class="teacher-popover"><label>자리표 크기<select id="seat-size"><option value="fit" ${teacherSeatScale==='fit'?'selected':''}>자동 맞춤</option><option value="large" ${teacherSeatScale==='large'?'selected':''}>크게 보기 · 필요하면 스크롤</option></select></label><p>자동 맞춤은 빈자리와 통로를 유지합니다. 더 크게 보려면 위 설정을 바꾸세요.</p><strong>서버 상태</strong><p>버전 ${snapshot.version}<br>마지막 확인 ${h(lastSync)} (한국 시간)</p><p>학생을 누르면 참여 +1. 저장 확인 후 표시됩니다. 취소는 발표 기록 창에서 가능합니다.</p><button id="logout">로그아웃</button></div></details></div><div class="teacher-nav"><nav class="tabs" aria-label="교사 화면">${[['class','수업·자리표'],['history','참여 기록·취소']].map(([v,l])=>`<button data-tab="${v}" class="${tab===v?'active':''}">${l}</button>`).join('')}</nav><small class="teacher-summary">재적 ${snapshot.students.length}명 · 사진 ${photos.length} · 누적 ${total}회<span id="today-total"></span></small></div></header>`;}
// Native details keeps the menus keyboard accessible; outside click/Escape closes them.
document.addEventListener('click',e=>{document.querySelectorAll('.teacher-tools details[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const opened=[...document.querySelectorAll('.teacher-tools details[open]')];opened.forEach(d=>d.open=false);opened[0]?.querySelector('summary')?.focus();}});

function stopTeacherSeatFit(){teacherFitObserver?.disconnect();teacherFitObserver=null;cancelAnimationFrame(teacherFitFrame);teacherFitFrame=0;}
function scheduleTeacherSeatFit(){if(teacherFitFrame)return;teacherFitFrame=requestAnimationFrame(()=>{teacherFitFrame=0;updateSeatPanHint();});}
function watchTeacherSeatFit(){
 if(admin())return;
 updateSeatPanHint();
 teacherFitObserver=new ResizeObserver(scheduleTeacherSeatFit);
 document.querySelectorAll('.teacher-tools,.teacher-view .classroom-panel>header,.teacher-view .warning,.teacher-view .seat-pan-hint,.teacher-view .grid-scroll').forEach(n=>teacherFitObserver.observe(n,{box:'border-box'}));
}
function updateSeatPanHint(){
 const panel=q('.teacher-view .classroom-panel'),scroller=panel?.querySelector('.grid-scroll'),hint=q('#seat-pan-hint');
 if(!scroller||!hint||!snapshot)return;
 const grid=scroller.querySelector('.seat-grid'),children=[...grid.children],l=snapshot.layout;
 if(children.length!==l.rows*l.cols)return;
 panel.classList.add('teacher-seating-fit');
 // Read the displayed coordinates, including the existing teacher-view reversal.
 const desk=n=>n.classList.contains('seat')||n.classList.contains('desk');
 const columns=Array.from({length:l.cols},(_,c)=>children.some((n,i)=>i%l.cols===c&&desk(n)));
 const rows=Array.from({length:l.rows},(_,r)=>children.slice(r*l.cols,(r+1)*l.cols).some(desk));
 const deskCols=columns.filter(Boolean).length,deskRows=rows.filter(Boolean).length;
 if(!deskCols||!deskRows)return;
 const gap=4,aisle=8,large=teacherSeatScale==='large',board=panel.querySelector('.board');
 const css=n=>getComputedStyle(n),px=(n,key)=>parseFloat(css(n)[key])||0;
 const availableHeight=()=>Math.max(120,Math.floor((window.visualViewport?.height??innerHeight)+(window.visualViewport?.offsetTop??0)-scroller.getBoundingClientRect().top-board.offsetHeight-px(board,'marginTop')-px(panel,'paddingBottom')-px(panel,'borderBottomWidth')-px(panel,'marginBottom')-px(panel.closest('main'),'paddingBottom')));
 const compact=!large&&(availableHeight()/deskRows<128||scroller.clientWidth/deskCols<144);
 panel.classList.toggle('seat-fit-dense',compact);
 const nameSize=compact?12:14,numberSize=compact?10:12,countSize=compact?11:13;
 panel.style.setProperty('--seat-name-size',nameSize+'px');panel.style.setProperty('--seat-number-size',numberSize+'px');panel.style.setProperty('--seat-count-size',countSize+'px');
 const textMin=Math.max(compact?42:58,...[...grid.querySelectorAll('.count-token')].map(n=>n.getBoundingClientRect().width));
 hint.hidden=true;
 let minHeight=large?116:64;
 const apply=()=>{
  const width=scroller.clientWidth,height=availableHeight();
  const cardWidth=Math.max(large?Math.max(134,textMin+84):textMin+(compact?44:58),(width-(l.cols-deskCols)*aisle-(l.cols-1)*gap)/deskCols);
  let cardHeight=Math.max(minHeight,(height-(l.rows-deskRows)*aisle-(l.rows-1)*gap)/deskRows);
  const setSizes=()=>{
   const scale=compact?1:Math.min(1.4,Math.max(1,Math.min(cardWidth/134,cardHeight/116)));
   const identityWidth=textMin*scale;
   const photoWidth=Math.max(compact?32:44,Math.min(cardWidth-identityWidth-12,(cardHeight-10)*.75));
   grid.style.gridTemplateColumns=columns.map(full=>(full?cardWidth:aisle)+'px').join(' ');
   grid.style.gridTemplateRows=rows.map(full=>(full?cardHeight:aisle)+'px').join(' ');
   scroller.style.height=height+'px';
   panel.classList.toggle('seat-compact',cardHeight<92);
   for(const [key,value]of Object.entries({'text-min':identityWidth,'photo-width':photoWidth,'photo-height':cardHeight-10,'name-size':nameSize*scale,'number-size':numberSize*scale,'count-size':countSize*scale}))panel.style.setProperty('--seat-'+key,value+'px');
  };
  setSizes();
  const textHeight=Math.max(0,...[...grid.querySelectorAll('.identity')].map(n=>n.scrollHeight))+(compact?30:38);
  if(textHeight>cardHeight){minHeight=Math.ceil(textHeight);cardHeight=minHeight;setSizes();}
  return {x:scroller.scrollWidth>scroller.clientWidth+1,y:scroller.scrollHeight>scroller.clientHeight+1};
 };
 let overflow=apply();
 if(overflow.x||overflow.y){hint.hidden=false;overflow=apply();hint.textContent=(overflow.x&&overflow.y?'↔ ↕ 좌우·위아래':overflow.x?'↔ 좌우':'↕ 위아래')+'로 밀어 전체 자리표 보기 · '+(large?'더보기에서 자동 맞춤으로 돌아갈 수 있습니다.':'글자 크기를 유지하려고 일부 자리는 스크롤로 표시합니다.');}
 scroller.dataset.seatSizing=teacherSeatScale;
}
