document.fonts?.ready.then(scheduleTeacherSeatFit);


function returnToClassroom(studentId=''){if(busy||!api.access||!course)return;studentHistoryEpoch++;dialog.close();tab='class';render();(studentId?q('[data-student-history="'+CSS.escape(studentId)+'"]'):q('[data-tab="class"]'))?.focus();}

// Student history uses the existing course-scoped, teacher/admin-only RPC.
let studentHistoryEpoch=0;
dialog.addEventListener('close',()=>{studentHistoryEpoch++;});
const historyDate=t=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(t));
async function openStudentHistory(studentId,afterWrite=false){
 if((busy&&!afterWrite)||!api.access||!['teacher','admin'].includes(course?.role)||!snapshot?.students.some(s=>s.id===studentId))return;
 const g=generation,id=course.id,epoch=++studentHistoryEpoch;
 const current=()=>g===generation&&id===course?.id&&epoch===studentHistoryEpoch&&dialog.open;
 modal('학생 발표 기록',`<p>${h(course.schoolYear??'')}학년도 ${h(course.term??'')}학기 · ${h(courseLabel(course))}</p><label>학생<select id="history-student">${snapshot.students.map(s=>`<option value="${h(s.id)}" ${s.id===studentId?'selected':''}>${h(s.number)} ${h(s.name)}</option>`).join('')}</select></label><p class="muted">한국 표준시 (KST, UTC+9) · 최신순 · 취소 이력 포함</p><p id="student-history-status" role="status">기록을 불러오는 중…</p><div id="student-history-list"></div>`,null);
 dialog.querySelector('.dialog-actions').remove();
 const back=dialog.querySelector('[data-close]');back.textContent='자리표로 돌아가기';back.setAttribute('aria-label','자리표로 돌아가기');back.onclick=()=>returnToClassroom(studentId);
 q('#history-student').onchange=e=>openStudentHistory(e.target.value);
 let all=[],cursor=null,seen=new Set();
 try{
  do{
   const result=await api.rpc('hafs_teacher_history',{p_course:id,p_before_at:cursor?.at??null,p_before_id:cursor?.id??null,p_limit:200,p_from:null,p_until:null});
   if(!current())return;
   all.push(...result.events.filter(e=>e.student_id===studentId));
   cursor=result.next;
   if(cursor){const key=JSON.stringify(cursor);if(seen.has(key))throw Error('조회 위치가 반복되었습니다. 다시 시도하세요.');seen.add(key);}
   q('#student-history-status').textContent=`기록을 불러오는 중… ${all.length}건 확인`;
  }while(cursor);
  if(!current())return;
  q('#student-history-status').textContent=`조회 완료 · 유효 ${all.filter(e=>!e.cancelled_at).length}회 · 취소 ${all.filter(e=>e.cancelled_at).length}회`;
  q('#student-history-list').innerHTML=all.length?`<div class="table-wrap"><table><thead><tr><th>발표 일시 (KST)</th><th>상태</th><th>취소</th></tr></thead><tbody>${all.map(e=>`<tr><td>${h(historyDate(e.at))}</td><td>${e.cancelled_at?`취소됨<br><small>${h(historyDate(e.cancelled_at))}</small>`:'발표'}</td><td>${e.cancelled_at?'—':`<button data-student-undo="${h(e.id)}">취소</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">이 학생의 발표 기록이 없습니다.</p>';
  dialog.querySelectorAll('[data-student-undo]').forEach(b=>b.onclick=e=>{if(e.detail>1)return;return act(async()=>{
   if(!current()||b.disabled)return;
   const buttons=[...dialog.querySelectorAll('[data-student-undo]')];buttons.forEach(n=>n.disabled=true);q('#history-student').disabled=true;
   q('#student-history-error')?.remove();q('#student-history-status').textContent='취소를 저장하는 중…';let saved=false;
   try{
    await api.rpc('hafs_undo',{p_course:id,p_event:b.dataset.studentUndo});saved=true;
    if(!current())return;
    q('#student-history-status').textContent='취소 저장됨 · 횟수와 기록을 다시 확인하는 중…';
    await refresh(true,true);
    if(!current())return;
    // act holds the write lock; reload without permitting a second write.
    await openStudentHistory(studentId,true);
   }catch(e){
    if(!current())return;
    if(e.status===401||e.status===403||/NOT_AUTHORIZED|AUTH_USER_INACTIVE/.test(e.message)){await signout('접근 권한을 확인할 수 없어 로그아웃했습니다.');return;}
    const warning=document.createElement('p');warning.id='student-history-error';warning.className='notice warning';warning.setAttribute('role','alert');warning.textContent=(saved?'취소는 저장되었지만 횟수 갱신에 실패했습니다.':'취소 결과를 확인하지 못했습니다. 중복 취소는 추가 차감되지 않습니다.')+' '+friendly(e);q('#student-history-list').prepend(warning);
    buttons.forEach(n=>n.disabled=false);q('#history-student').disabled=false;
   }
  });});
 }catch(e){
  if(!current())return;
  if(e.status===401||e.status===403||/NOT_AUTHORIZED|AUTH_USER_INACTIVE/.test(e.message)){await signout('접근 권한을 확인할 수 없어 로그아웃했습니다.');return;}
  q('#student-history-status').textContent='조회 실패';
  q('#student-history-list').innerHTML=`<p id="student-history-error" class="notice warning" role="alert">${h(friendly(e))}</p><button id="student-history-retry">다시 조회</button>`;
  q('#student-history-retry').onclick=()=>openStudentHistory(studentId);
 }
}

// Tokens remain in memory only. BFCache can restore that memory; a new document cannot.
let restoringPage=null;
async function restorePage(){
 if(restoringPage)return restoringPage;
 if(!api.access){app.hidden=false;login();return;}
 const g=++generation,selected=course?.id;studentHistoryEpoch++;dialog.close();app.hidden=true;
 loading=false;snapshot=null;photos=[];roster=[];queue=[];audit=[];historyData=null;
 restoringPage=(async()=>{
  try{
   const next=await api.rpc('hafs_my_courses');if(g!==generation||!api.access)return;
   courses=next;course=courses.find(c=>c.id===selected)??initialCourse(courses);tab='class';
   render();if(course)await refresh(true);
  }catch(e){
   if(g!==generation)return;
   if(e.status===401||e.status===403||/NOT_AUTHORIZED|AUTH_USER_INACTIVE/.test(e.message))await signout('세션 또는 학급 권한이 만료되었습니다. 다시 로그인하세요.');
   else{app.innerHTML='<main><h1>로그인 상태 확인</h1><p>연결을 확인하지 못했습니다. 학생 자료는 다시 확인한 뒤 표시합니다.</p><button id="restore-retry">다시 확인</button><button id="restore-logout">로그아웃</button></main>';q('#restore-retry').onclick=()=>restorePage();q('#restore-logout').onclick=()=>signout();}
  }finally{app.hidden=false;restoringPage=null;}
 })();
 return restoringPage;
}
window.addEventListener('pagehide',()=>{app.hidden=true;studentHistoryEpoch++;dialog.close();});
window.addEventListener('pageshow',e=>{if(e.persisted)restorePage();else app.hidden=false;});
window.addEventListener('popstate',()=>{if(api.access)restorePage();});
